  assert.equal(parseAndClamp('0', '0', '10'), 0);
  assert.equal(parseAndClamp('10', '0', '10'), 10);
  assert.equal(parseAndClamp('5', '2', '2'), 2);
});
test('WI-005 全引数の入力例外と逆順境界の例外を維持する', () => {
  for (const invalid of ['', ' \t', 'abc', 'NaN', 'Infinity', '-Infinity']) {
    for (const args of [[invalid, '0', '10'], ['5', invalid, '10'], ['5', '0', invalid]] as const) {
      assert.throws(() => parseAndClamp(...args), { name: 'TypeError', message: 'invalid bound' });
    }
  }
  assert.throws(() => parseAndClamp('5', '10', '0'), { name: 'RangeError', message: 'minimum must be less than or equal to maximum' });
  assert.throws(() => parseAndClamp('abc', '10', '0'), { name: 'TypeError', message: 'invalid bound' });
