test('上限より大きい値は上限になる', () => assert.equal(clamp(11, 0, 10), 10));
test('境界値は変えない', () => { assert.equal(clamp(0, 0, 10), 0); assert.equal(clamp(10, 0, 10), 10); });
test('同じ上下限はその値になる', () => assert.equal(clamp(5, 2, 2), 2));
test('逆順境界は指定例外になる', () => assert.throws(() => clamp(5, 10, 0), { name: 'RangeError', message: 'minimum must be less than or equal to maximum' }));
test('非有限valueは他の検査より先に拒否される', () => { for (const value of [NaN, Infinity, -Infinity]) assert.throws(() => clamp(value, Infinity, 0), { name: 'TypeError', message: 'value must be finite' }); });
test('非有限境界は順序の検査より先に拒否される', () => { for (const [min, max] of [[NaN, 0], [0, Infinity], [-Infinity, 0]]) assert.throws(() => clamp(5, min, max), { name: 'TypeError', message: 'bounds must be finite' }); });

// @work-item-id WI-003
import { clamp01 } from '../scripts/harness/counter/domain/clamp.ts';

test('clamp01は正常値・範囲外・境界で固定区間clampと一致する', () => {
  for (const [value, expected] of [
    [0.5, 0.5], [-1, 0], [2, 1], [0, 0], [1, 1],
    [-0, 0], [-Number.MAX_VALUE, 0], [Number.MAX_VALUE, 1],
  ]) {
    assert.equal(clamp01(value), expected);
    assert.equal(clamp01(value), clamp(value, 0, 1));
  }
});

test('clamp01は非有限値をclampと同じ例外型・messageで拒否する', () => {
  for (const value of [NaN, Infinity, -Infinity]) {
    let baseline: unknown;
    try { clamp(value, 0, 1); } catch (error) { baseline = error; }
    assert.ok(baseline instanceof TypeError);
    const expectedError = baseline;
    assert.throws(() => clamp01(value), (error: unknown) => {
      assert.ok(error instanceof TypeError);
      assert.equal(error.constructor, TypeError);
      assert.equal(error.message, 'value must be finite');
      assert.equal(error.constructor, expectedError.constructor);
      assert.equal(error.message, expectedError.message);
      return true;
    });
  }
});

